"""This function is a decorator that can be used to mark functions as deprecated. It will result in a warning being emitted when the function is used.

:param reason: String. The reason for deprecation.
:return: Callable. A callable object that can be used as a decorator.
"""

def decorator(func1: Callable) -> Callable:
    if isinstance(func1, partial):
        return partial(
            decorator, func1.func
        )(*func1.args, **func1.keywords)

    @functools.wraps(func1)
    def new_func1(*args: Any, **kwargs: Any) -> Any:
        warnings.simplefilter("always", DeprecationWarning)
        warnings.warn_explicit(
            "Call to deprecated function {}. ({})".format(
                func1.__name__, reason
            ),
            category=DeprecationWarning,
            filename=func1.__code__.co_filename,
            lineno=func1.__code__.co_firstlineno + 1,
        )
        warnings.simplefilter("default", DeprecationWarning)
        return func1(*args, **kwargs)

    return new_func1

return decorator

