:param lines: List[str]. The sequence of lines to parse.
:return: Generator. Yields dict representing each record, with 'fields', 'num_lines', 'start_line' and 'type' as keys.
"""
record = None
for line_num, line in enumerate(lines):
    if line.startswith('type'):
        record = {'fields': {}, 'num_lines': 1, 'start_line': line_num, 'type': 'type'}
        continue
    if line.startswith('.'):
        yield record
        record = None
        continue
    if record is None:
        raise ValueError('Unexpected line: %s' % line)
    record['num_lines'] += 1
    for field_name, field_value in _parse_fields(line):
        record['fields'][field_name] = field_value

