:return: DropConstraintOp. The created DropConstraintOp instance.
"""
if isinstance(constraint, UniqueConstraint):
    return cls(
        constraint.name,
        table_name=constraint.table.name,
        columns=[c.name for c in constraint.columns],
    )
elif isinstance(constraint, CheckConstraint):
    return cls(
        constraint.name,
        table_name=constraint.table.name,
        text=constraint.expression.text,
    )
elif isinstance(constraint, ForeignKeyConstraint):
    return cls(
        constraint.name,
        table_name=constraint.table.name,
        columns=[col.name for col in constraint.columns],
        referent_table=constraint.referred_table.name,
        referent_columns=[col.name for col in constraint.referred_columns],
        ondelete=constraint.ondelete,
        onupdate=constraint.onupdate,
    )
elif isinstance(constraint, PrimaryKeyConstraint):
    return cls(
        constraint.name,
        table_name=constraint.table.name,
        columns=constraint.columns,
    )
else:
