:return: Tuple. A pair of deserialized values.
"""
raw_value = value.strip()
if not raw_value:
    return None, None
if self.separator in raw_value:
    parts = raw_value.split(self.separator, 1)
    if len(parts) == 1:
        if self.optional_pair:
            parts.append(parts[0])
        else:
            raise ValueError(
                "Config value must include separator: %r" % raw_value
            )
    return self.subtypes[0].deserialize(parts[0]), self.subtypes[1].deserialize(
        parts[1]
    )
else:
    if self.optional_pair:
        return self.subtypes[0].deserialize(raw_value), self.subtypes[0].deserialize(
            raw_value
        )
    else:
        raise ValueError("Config value must include separator: %r" % raw_value)

