"""This function takes a format string and converts it into a list of alternating string literals and BaseFormatField tokens. It also has an option to infer anonymous positional references into explicit, numbered positional references.

:param fstr: String. The format string to be tokenized.
:param resolve_pos: Bool. Whether to infer anonymous positional references into explicit, numbered positional references. Defaults to True.
:return: List. A list of alternating string literals and BaseFormatField tokens.
"""
tokens = []
pos = 0
while pos < len(fstr):
    if fstr[pos] == '{':
        if fstr[pos + 1] == '{':
            tokens.append('{')
            pos += 2
        else:
            start = pos + 1
            end = start
            while end < len(fstr) and fstr[end] not in '}}':
                if fstr[end] == ':':
                    break
                end += 1
            if end == len(fstr):
                raise ValueError('Unclosed format field')
            if fstr[end] == ':':
                tokens.append(fstr[start:end])
                pos = end + 1
                start = pos
                while pos < len(fstr) and fstr[pos] not in '}}':
                    pos += 1
                if pos == len(fstr):
                    raise ValueError('Unclosed format field')
                tokens.append(fstr[start:pos])
                pos += 1
            else:
                tokens.append(fstr[start:end])
                pos = end + 1
    else:
        start = pos
        while pos < len(fstr) and fstr[pos] != '{':
            pos += 1
        tokens.append(fstr[start:pos])
if resolve_pos:
    pos = 0
    for i, token in enumerate(tokens):
        if isinstance(token, str):
            if token.startswith('{') and token.endswith('}'):
                if token[1] == '{':
                    tokens[i] = '{' + str(pos) + '}'
                    pos += 1
                else:
                    tokens[i] = '{' + token[1:] + '}'
return tokens

