:param df: pd.DataFrame. The input DataFrame.
:param summary: dict. A dictionary that summarizes the properties of each column in the DataFrame.
:return: Optional[pd.DataFrame]. The correlation matrix if there are more than one numerical or categorical columns, otherwise None.
"""
# Identify numerical and categorical columns
numerical_columns = [
    column
    for column, summary_ in summary.items()
    if summary_.dtype == "Numerical"
]
categorical_columns = [
    column
    for column, summary_ in summary.items()
    if summary_.dtype == "Categorical"
]

# Discretize numerical columns
if len(numerical_columns) > 0:
    df_numerical = df[numerical_columns]
    df_numerical = discretize_numerical(
        df_numerical, config.correlations.numerical_methods
    )

# Calculate correlation scores
if len(numerical_columns) > 1:
    correlation_matrix = calculate_correlation_matrix(
        df_numerical, config.correlations.correlation_method
    )
elif len(categorical_columns) > 1:
    correlation_matrix = calculate_correlation_matrix(
        df[categorical_columns], config.correlations.correlation_method
    )
else:
    return None

return correlation_matrix

