"""This function determines the type of a file based on its content. It checks the file's XML structure and content types to identify if it is a Word document, Excel spreadsheet, PowerPoint presentation, or none of these.

:param filename: String. The name of the file to be checked.
:return: Integer. One of the DOCTYPE_* constants indicating the type of the file.
"""
import xml.etree.ElementTree as ET
import zipfile

DOCTYPE_NONE = 0
DOCTYPE_WORD = 1
DOCTYPE_EXCEL = 2
DOCTYPE_PPT = 3

try:
    with zipfile.ZipFile(filename) as zf:
        if '[Content_Types].xml' in zf.namelist():
            with zf.open('[Content_Types].xml') as f:
                root = ET.fromstring(f.read())
                for child in root:
                    if child.tag == '{http://schemas.openxmlformats.org/package/2006/content-types}Default':
                        if child.attrib['ContentType'] == 'application/vnd.openxmlformats-officedocument.wordprocessingml.document':
                            return DOCTYPE_WORD
                        elif child.attrib['ContentType'] == 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet':
                            return DOCTYPE_EXCEL
                        elif child.attrib['ContentType'] == 'application/vnd.openxmlformats-officedocument.presentationml.presentation':
                            return DOCTYPE_PPT
except:
    pass

return DOCTYPE_NONE

