    "Attachment.InstanceId": instance_id,
    "Attachment.DeviceIndex": device_index,
    "DryRun": dry_run,
}

response = self.connection.request(
    action="AttachNetworkInterface",
    params=params,
    method="POST",
    data={"NetworkInterfaceId": self.id},
)

if response.status == 200:
    return True
else:
    return False

